import 'server-only';
import manifest from './imageManifest.json';

/** Real size and blurred preview of an image (generated by `npm run images:manifest`). */
export interface MediaMeta {
  width: number;
  height: number;
  /** Tiny WebP data URL shown blurred while the full image loads. */
  blur: string;
}

export type MediaMap = Record<string, MediaMeta>;

const MANIFEST: MediaMap = manifest;

/** Manifest entries for the given image paths only, so a page ships just what it shows. */
export function mediaFor(sources: Iterable<string | null | undefined>): MediaMap {
  const media: MediaMap = {};
  for (const src of sources) {
    if (src && MANIFEST[src]) media[src] = MANIFEST[src];
  }
  return media;
}
